// Today's date in the workflow's timezone (menu > Settings > Timezone)
const today = $now.toFormat('yyyy-MM-dd');

// Keep today's jobs, drop cancelled ones, earliest first
const jobs = $input.all().map(i => i.json)
  .filter(j => String(j.date) === today && j.status !== 'Cancelled')
  .sort((a, b) => String(a.time).localeCompare(String(b.time)));

// One line per job: time, customer, address, job, tech
const lines = jobs.map(j => `${j.time}  ${j.customer}, ${j.address} - ${j.job} (${j.tech})`);

return [{ json: {
  count: jobs.length,
  first: jobs.length ? jobs[0].time : 'none',
  day: $now.toFormat('cccc d LLLL'),
  list: lines.join('\n') || 'No jobs booked today.'
} }];

